public static int findNthLeapYear(int Y, int N) {
    // Validate inputs
    if (Y <= 0 || N <= 0) {
        throw new IllegalArgumentException("Y and N must be positive integers.");
    }

    int year = Y;
    int count = 0;
    while (true) {
        // Check if current year is a leap year
        if ((year % 400 == 0) || (year % 4 == 0 && year % 100 != 0)) {
            count++;
            if (count == N) {
                return year;
            }
        }
        year++;
        // Prevent infinite loop in case of integer overflow
        if (year < 0) {
            throw new RuntimeException("Year overflow while searching for nth leap year.");
        }
    }
}

public static int findNthLeapYear(int Y, int N) {
    if (Y <= 0 || N <= 0) {
        throw new IllegalArgumentException("Both Y and N must be positive integers.");
    }
    int count = 0;
    int year = Y;
    while (true) {
        // Determine if the current year is a leap year
        boolean isLeap = (year % 400 == 0) || (year % 4 == 0 && year % 100 != 0);
        if (isLeap) {
            count++;
            if (count == N) {
                return year;
            }
        }
        year++;
        // Prevent potential infinite loop in case of integer overflow
        if (year == Integer.MAX_VALUE) {
            throw new RuntimeException("Exceeded integer range while searching for leap year.");
        }
    }
}

